const app=document.querySelector('#robot-app'),wrap=document.querySelector('#stage-wrap'),dialog=document.querySelector('#robot-dialog'),content=document.querySelector('#dialog-content');
const paths={robot:'M5 7h14v13H5ZM9 11h1m4 0h1M9 16h6M12 7V3m-1 0h2M2 11v5m20-5v5',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7',screen:'M3 4h18v13H3ZM8 21h8m-4-4v4',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',pause:'M9 5v14M15 5v14',play:'m8 4 12 8-12 8Z',reset:'M4 9a8 8 0 1 1-1 6M4 3v6h6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l4 3',battery:'M2 7h18v10H2ZM23 10v4M5 10h10v4H5Z',task:'M5 4h14v17H5ZM9 4V2h6v2M8 9h8M8 13h8M8 17h4',alert:'m12 3 10 18H2ZM12 9v5m0 3v.2',signal:'M3 9q9-9 18 0M6 12q6-6 12 0M9 15q3-3 6 0M12 19v.1',arrow:'m9 5 7 7-7 7',check:'m5 12 4 4L20 5',minus:'M5 12h14',plus:'M12 5v14M5 12h14'};const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.robot}"/></svg>`;
const robots=[{id:'R-01',name:'轨道巡检机器人',area:'中央运输巷',battery:78,status:'巡检中',task:'日常巡检 · A线',progress:72,position:'34.52',speed:'.12',online:true},{id:'R-02',name:'吊轨巡检机器人',area:'N302 工作面',battery:14,status:'低电量',task:'设备检查 · B线',progress:46,position:'86.24',speed:'.08',online:true},{id:'R-03',name:'工作面巡检机器人',area:'N302 工作面',battery:62,status:'离线',task:'待恢复通信',progress:0,position:'—',speed:'—',online:false}];
const alerts=[{title:'吊轨机器人电量偏低',id:'R-02',time:'10:21:08',value:'14%',type:'电量提醒',ack:false},{title:'采集温度超过演示阈值',id:'R-01',time:'10:18:32',value:'53.2 ℃',type:'温度提醒',ack:false},{title:'工作面机器人通信中断',id:'R-03',time:'10:16:04',value:'离线',type:'通信提醒',ack:false}];
let mode=new URLSearchParams(location.search).get('view')==='monitor'?'monitor':'overview',selected=0,scene,motion=!matchMedia('(prefers-reduced-motion: reduce)').matches,command='idle',speed=.12,tick=0,lastFocus,commandTimer,disposed=false;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fit(){const w=innerWidth,h=innerHeight;const scale=Math.min(w/1760,h/990);app.style.transform=`scale(${scale})`;wrap.style.width=1760*scale+'px';wrap.style.height=990*scale+'px';wrap.style.marginTop=Math.max(0,(h-990*scale)/2)+'px'}
function tag(text,c='online'){return `<span class="tag ${c}">${text}</span>`}function panel(title,body,cls='',side=''){return `<section class="panel ${cls}"><div class="panel-head"><h2>${title}</h2>${side||'<small>LIVE / DEMO</small>'}</div>${body}</section>`}
function metric(label,value,unit,i,note,cls=''){return `<article class="metric ${cls}"><div><span class="metric-label">${label}</span><div class="metric-value"><strong>${value}</strong><small>${unit}</small></div></div><span class="metric-icon">${icon(i)}</span><small>${note}</small></article>`}
function devices(){return `<div class="device-list">${robots.map((r,i)=>`<button class="device-row ${i===selected?'active':''} ${!r.online?'offline':i===1?'amber':''}" data-robot="${i}" aria-pressed="${i===selected}"><span class="device-symbol"><img src="assets/robot/robot-source.png" alt=""></span><span class="device-name"><b>${r.name}</b><small>${r.id} / ${r.area}</small><span class="battery-line"><i style="width:${r.battery}%"></i></span></span><span class="dot"></span></button>`).join('')}</div>`}
function taskTable(){return `<table class="data-table"><thead><tr><th style="width:27%">巡检任务</th><th>执行设备</th><th style="width:21%">任务进度</th><th>开始时间</th><th>状态</th></tr></thead><tbody>${robots.map((r,i)=>`<tr tabindex="0" data-task="${i}" role="button" aria-label="查看${r.task}任务"><td>${r.task}</td><td>${r.id}</td><td><span class="progress"><i><b style="width:${r.progress}%"></b></i>${r.progress}%</span></td><td>${['08:30:00','09:15:00','—'][i]}</td><td>${r.online?'<span style="color:#648e84">执行中</span>':'<span style="color:#596c76">已中断</span>'}</td></tr>`).join('')}</tbody></table>`}
function trend(){return `<svg class="trend-svg" viewBox="0 0 280 110" aria-label="演示任务趋势图"><defs><linearGradient id="chart-fill" x2="0" y2="1"><stop stop-color="#5ed0c6" stop-opacity=".12"/><stop offset="1" stop-color="#5ed0c6" stop-opacity="0"/></linearGradient></defs><g stroke="#6c9ea50b"><path d="M15 20H265M15 45H265M15 70H265M15 95H265"/></g><path d="M15 70 36 62 57 71 78 51 99 54 120 42 141 47 162 29 183 35 204 23 225 30 246 20 265 26V100H15Z" fill="url(#chart-fill)"/><path d="M15 70 36 62 57 71 78 51 99 54 120 42 141 47 162 29 183 35 204 23 225 30 246 20 265 26" fill="none" stroke="#6db9b4" stroke-width="1.7"/><path d="M15 90 36 84 57 89 78 77 99 81 120 70 141 71 162 61 183 65 204 55 225 60 246 48 265 51" fill="none" stroke="#a48f67" stroke-width="1.2" stroke-dasharray="3 3"/></svg><div class="chart-labels"><span>06:00</span><span>09:00</span><span>12:00</span><span>15:00</span><span>18:00</span></div>`}
function alertList(){return `<div class="alert-list">${alerts.map((a,i)=>`<button class="alert-item ${a.ack?'ack':''}" data-alert="${i}"><small>${a.time} / ${a.id}</small><span class="alert-state">${a.ack?'已知悉':'待关注'}</span><strong>${a.title}</strong><p>${a.type} · ${a.value}　${icon('arrow')}</p></button>`).join('')}</div>`}
function spatial(){return `<section class="spatial-panel"><div class="spatial-top"><div><h2>${mode==='overview'?'多场景设备拓扑':'N302 工作面 · 空间视图'}</h2><small>${mode==='overview'?'SPATIAL OPERATIONS NETWORK':'WORKFACE DIGITAL SCENE'} / CONCEPT</small></div>${tag('概念空间模型','')}</div><canvas class="spatial-canvas" id="spatial-canvas" role="img" aria-label="可旋转的机器人${mode==='overview'?'空间拓扑':'工作面'}场景，支持拖动与缩放"></canvas><span class="scene-marker">${robots[selected].id} / ${robots[selected].name} · ${robots[selected].status}</span><span class="scene-hint">拖动旋转 · 右侧按钮缩放 / ${mode==='overview'?'概览场景':'工作面场景'}</span><div class="scene-tools"><button data-action="rotate" aria-label="${scene?.auto?'停止旋转':'启动旋转'}">${icon(scene?.auto?'pause':'play')}</button><button data-action="zoom-in" aria-label="放大空间场景">${icon('plus')}</button><button data-action="zoom-out" aria-label="缩小空间场景">${icon('minus')}</button><button data-action="reset" aria-label="重置空间视角">${icon('reset')}</button></div></section>`}
function video(){const r=robots[selected];return `<div class="video-frame ${r.online?'':'offline'}"><img src="assets/robot/scene-source.png" alt="原稿工作面静态场景素材"><span class="static-tag">CAM 01 / 静态演示素材</span><span class="video-caption"><span>${r.area}</span><span>${r.id}</span></span>${!r.online?'<div class="offline-cover"><p>摄像头未连接<br>等待设备恢复通信</p></div>':''}</div><div class="video-label"><span>关联设备 ${r.id}</span>${tag(r.online?'画面示意':'离线',r.online?'online':'offline')}</div><div class="video-frame"><img src="assets/robot/scene-source.png" alt="工作面局部示意" style="object-position:80% 50%;transform:scale(1.3)"><span class="static-tag">CAM 02 / 局部观察</span><span class="video-caption"><span>支架区域</span><span>参考画面</span></span></div>`}
function selectedDetail(){const r=robots[selected];return `<div class="selected-robot"><img src="assets/robot/robot-source.png" alt="原稿机器人模型素材"><div><h3>${r.name}</h3><p>${r.id} / ${r.area}<br>${r.online?'已连接 · 状态可用':'通信离线 · 控制不可用'}</p></div></div><div class="detail-pairs"><div><small>当前电量</small><b>${r.battery}%</b></div><div><small>当前位置</small><b>${r.position}${r.online?' m':''}</b></div><div><small>任务进度</small><b>${r.progress}%</b></div></div>`}
function controls(){const r=robots[selected];return `<div class="control-body"><p class="control-context"><span>控制对象 ${r.id}</span><span>${r.online?'手动演示':'设备离线'}</span></p><div class="control-range"><input id="speed" type="range" min="0.02" max="0.3" step="0.01" value="${speed}" aria-label="演示移动速度" ${r.online?'':'disabled'}><output id="speed-output">${speed.toFixed(2)} m/s</output></div><div class="control-buttons"><button class="primary-action" data-action="command" ${r.online?'':'disabled'}>${icon('play')}模拟启动</button><button class="secondary-action" data-action="stop" ${r.online?'':'disabled'}>停止</button></div><p class="control-status" id="control-status">${!r.online?'通信不可用，已禁用控制操作':command==='running'?'模拟执行中 · 指令已响应':'就绪 · 请复核对象与参数'}</p><p class="control-note">本地交互演示，不连接真实机器人。</p></div>`}
function render(){const old=scene?{yaw:scene.yaw,pitch:scene.pitch,zoom:scene.zoom,time:scene.time,auto:scene.auto}:null;scene?.dispose();app.className=(mode==='monitor'?'monitor ':'')+(!motion?'is-paused':'');const n=alerts.filter(a=>!a.ack).length;app.innerHTML=`<header class="app-header"><div class="brand"><span class="brand-mark">R</span><div><strong>机器人智能管控平台</strong><small>ROBOTICS / OPERATIONS PLATFORM</small></div></div><nav class="primary-tabs" aria-label="核心界面切换"><button data-view="overview" class="${mode==='overview'?'active':''}" aria-current="${mode==='overview'?'page':'false'}">运行总览</button><button data-view="monitor" class="${mode==='monitor'?'active':''}" aria-current="${mode==='monitor'?'page':'false'}">工作面监控</button></nav><div class="header-end"><span class="live-dot">演示系统运行中</span><div class="clock"><b id="clock">10:24:08</b><small>2026.11.01 / SUNDAY</small></div><button class="utility" data-action="fullscreen" aria-label="全屏查看大屏">${icon('expand')}</button></div></header><div class="page-heading"><div><h1>${mode==='overview'?'机器人巡检指挥中心':'工作面巡检监控'}</h1><p>${mode==='overview'?'从全局状态，到每一台设备的现场。':'N302 WORKFACE / 当前对象 '+robots[selected].id+' / 场景、设备与任务同步可见'}</p></div><div class="heading-actions"><button class="scene-selector" data-action="select-scene">${mode==='overview'?'全部巡检场景':'N302 工作面场景'}　⌄</button>${tag('本地演示数据','')}<button class="text-control" data-action="motion">${icon(motion?'pause':'play')}<span>${motion?'暂停动效':'恢复动效'}</span></button></div></div><div class="metrics">${metric('在线机器人','12','/ 16 台','robot','在线率 75%')}${metric('今日巡检任务','24','项','task','已完成 21 项')}${metric('任务完成率','87.5','%','signal','21 / 24 项')}${metric('待关注异常',n,'条','alert',n?'点击右侧查看详情':'全部已知悉','warning')}</div><div class="dashboard-grid"><aside class="side-stack">${mode==='overview'?panel('关键设备',devices(),'device-panel','<small>3 / 16 DEVICES</small>')+panel('今日任务分布',`<div class="donut-wrap"><div class="donut"></div><div class="donut-center"><b>87.5<small style="display:inline;font-size:10px">%</small></b><small>任务完成率</small></div></div><div class="legend"><span><i></i>已完成 21</span><span><i></i>未完成 3</span></div>`,'donut-panel'):panel('关联现场画面',video(),'video-panel')+panel('现场声音参考',`<div class="scan-img"><img src="assets/robot/scan-source.png" alt="原稿声音波形静态素材"><i class="scan-beam"></i></div>`,'scan-panel')}</aside><div class="main-stack">${spatial()}${panel('当前巡检任务',taskTable(),'task-panel',`<button data-action="tasks">3 项关键任务 ↗</button>`)}</div><aside class="side-stack">${mode==='overview'?panel('巡检任务趋势',`<div class="chart-legend"><span><i></i>任务量</span><span><i></i>完成量</span></div>${trend()}`,'trend-panel')+panel('异常与提醒',alertList(),'alerts-panel',`<small>${n} 条待关注</small>`):panel('当前机器人',selectedDetail(),'robot-detail',`<button data-action="select-robot">切换设备 ↗</button>`)+panel('现场采集信息',`<div class="sensor-grid"><div><small>氧气</small><b>20.8<em>%</em></b></div><div><small>一氧化碳</small><b>0<em>ppm</em></b></div><div class="amber"><small>采集温度</small><b>53.2<em>℃</em></b></div><div><small>硫化氢</small><b>0.5<em>ppm</em></b></div><div><small>甲烷</small><b>0.3<em>%</em></b></div><div><small>数据状态</small><b style="font-size:10px">${robots[selected].online?'示意值':'已断开'}</b></div></div>`,'environment-panel',`<button data-alert="1">查看异常 ↗</button>`)+panel('机器人控制',controls(),'control-panel')}</aside></div><footer class="data-footer"><span><span class="live-dot">界面优化与动效演示</span><i class="mini-line"></i>概念空间模型 / 原稿静态素材 / 本地示例数据</span><span class="system-code">DESIGNED BY ZHU NING　/　UX · UI · VISUALIZATION</span></footer>`;scene=new RobotScene(document.querySelector('#spatial-canvas'),mode);if(old){scene.yaw=old.yaw;scene.pitch=old.pitch;scene.zoom=old.zoom;scene.time=old.time;scene.auto=old.auto}scene.selected=selected;scene.auto=motion&&scene.auto;scene.paused=!motion;const rotateButton=document.querySelector('[data-action=rotate]');rotateButton.innerHTML=icon(scene.auto?'pause':'play');rotateButton.setAttribute('aria-label',scene.auto?'停止旋转':'启动旋转');document.querySelector('#spatial-canvas').addEventListener('scene-pause',()=>{const b=document.querySelector('[data-action=rotate]');b.innerHTML=icon('play');b.setAttribute('aria-label','启动旋转')});fit()}
function changeView(v){if(!['overview','monitor'].includes(v))return;mode=v;command='idle';clearTimeout(commandTimer);render();scene.reset();scene.auto=motion;history.replaceState({},'',`?view=${mode}`)}
function toast(t){const n=document.querySelector('#demo-toast');n.textContent=t;n.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.classList.remove('show'),2600)}
function show(html){lastFocus=document.activeElement;content.innerHTML=html;if(!dialog.open)dialog.showModal();document.querySelector('.dialog-close').focus()}
const pair=(a,b)=>`<div class="dialog-pair"><span>${a}</span><b>${esc(b)}</b></div>`;
function alertDialog(i){const a=alerts[i];show(`<div class="dialog-eyebrow">EVENT DETAIL / ${a.type}</div><h2 class="dialog-title dialog-alert">${a.title}</h2>${pair('关联设备',a.id)}${pair('发生时间','2026.11.01 '+a.time)}${pair('采集值',a.value)}${pair('处理状态',a.ack?'已知悉':'待关注')}<p class="dialog-note">“确认知悉”仅记录已阅读，不表示异常已解决。数值和事件均用于本地演示。</p><div class="dialog-actions"><button class="secondary-action" data-action="locate-alert" data-id="${i}">定位关联设备</button><button class="primary-action" data-action="ack" data-id="${i}" ${a.ack?'disabled':''}>确认知悉</button></div>`)}
app.addEventListener('click',e=>{const b=e.target.closest('button,[data-task]');if(!b)return;if(b.dataset.view){changeView(b.dataset.view);return}if(b.dataset.robot!==undefined){selected=+b.dataset.robot;command='idle';speed=selected===1?.08:.12;render();toast('已选中 '+robots[selected].id+'，关联状态已同步');return}if(b.dataset.alert!==undefined){alertDialog(+b.dataset.alert);return}if(b.dataset.task!==undefined){taskDialog(+b.dataset.task);return}switch(b.dataset.action){case'motion':motion=!motion;scene.paused=!motion;scene.auto=motion;app.classList.toggle('is-paused',!motion);b.innerHTML=icon(motion?'pause':'play')+'<span>'+(motion?'暂停动效':'恢复动效')+'</span>';break;case'rotate':scene.auto=!scene.auto;if(scene.auto){scene.paused=false;motion=true;app.classList.remove('is-paused')}b.innerHTML=icon(scene.auto?'pause':'play');b.setAttribute('aria-label',scene.auto?'停止旋转':'启动旋转');break;case'zoom-in':scene.zoom=Math.min(1.6,scene.zoom+.15);break;case'zoom-out':scene.zoom=Math.max(.65,scene.zoom-.15);break;case'reset':scene.reset();toast('已恢复默认空间视角');break;case'fullscreen':toggleFull();break;case'select-scene':show(`<div class="dialog-eyebrow">SCENE NAVIGATION</div><h2 class="dialog-title">选择观察视角</h2><p class="dialog-note">本次制作运行总览与N302工作面两个核心界面。切换后保留当前机器人选择。</p><div class="dialog-actions"><button class="secondary-action" data-target-view="overview">运行总览</button><button class="primary-action" data-target-view="monitor">N302 工作面</button></div>`);break;case'select-robot':show(`<div class="dialog-eyebrow">DEVICE CONTEXT</div><h2 class="dialog-title">选择当前机器人</h2><div class="device-list">${robots.map((r,i)=>`<button class="device-row" data-dialog-robot="${i}"><span class="device-name"><b>${r.id} / ${r.name}</b><small>${r.status} · 电量 ${r.battery}%</small></span>${icon('arrow')}</button>`).join('')}</div>`);break;case'tasks':show(`<div class="dialog-eyebrow">TASK OVERVIEW</div><h2 class="dialog-title">当前关键任务</h2>${robots.map((r,i)=>`<button class="device-row" data-dialog-task="${i}"><span class="device-name"><b>${r.task}</b><small>${r.id} · ${r.progress}% · ${r.status}</small></span>${icon('arrow')}</button>`).join('')}`);break;case'command':if(!robots[selected].online)return;show(`<div class="dialog-eyebrow">COMMAND PREVIEW / SIMULATION</div><h2 class="dialog-title">复核本次模拟操作</h2>${pair('当前设备',robots[selected].id+' / '+robots[selected].name)}${pair('模拟速度',speed.toFixed(2)+' m/s')}${pair('操作','模拟启动')}<p class="dialog-note">本演示仅改变本地界面状态，不发送任何实际设备指令。</p><div class="dialog-actions"><button class="secondary-action" data-action="close">返回检查</button><button class="primary-action" data-action="send-command">确认模拟启动</button></div>`);break;case'stop':clearTimeout(commandTimer);command='stopped';document.querySelector('#control-status').textContent='已停止模拟 · 本地状态已更新';toast('模拟已停止');break;}});
function taskDialog(i){const r=robots[i];show(`<div class="dialog-eyebrow">INSPECTION TASK</div><h2 class="dialog-title">${r.task}</h2>${pair('关联机器人',r.id)}${pair('当前场景',r.area)}${pair('执行进度',r.progress+'%')}${pair('设备状态',r.status)}<div class="dialog-status-strip"><i style="width:${r.progress}%"></i></div><div class="dialog-actions"><button class="primary-action" data-dialog-robot="${i}" data-to-monitor="true">进入关联监控</button></div>`)}
dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b){if(e.target===dialog)dialog.close();return}if(b.classList.contains('dialog-close')||b.dataset.action==='close'){dialog.close();return}if(b.dataset.targetView){dialog.close();changeView(b.dataset.targetView);return}if(b.dataset.dialogRobot!==undefined){selected=+b.dataset.dialogRobot;dialog.close();speed=selected===1?.08:.12;if(b.dataset.toMonitor)changeView('monitor');else render();return}if(b.dataset.dialogTask!==undefined){taskDialog(+b.dataset.dialogTask);return}if(b.dataset.action==='ack'){alerts[+b.dataset.id].ack=true;dialog.close();render();toast('已记录知悉，异常状态仍需跟进')}if(b.dataset.action==='locate-alert'){selected=robots.findIndex(r=>r.id===alerts[+b.dataset.id].id);speed=selected===1?.08:.12;dialog.close();changeView('monitor');toast('已定位关联设备 '+robots[selected].id)}if(b.dataset.action==='send-command'){dialog.close();command='sending';document.querySelector('#control-status').textContent='正在模拟发送指令…';commandTimer=setTimeout(()=>{if(mode!=='monitor')return;command='running';document.querySelector('#control-status').textContent='模拟执行中 · 设备已响应';toast('模拟指令已响应')},1000)}});
dialog.addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());app.addEventListener('input',e=>{if(e.target.id==='speed'){speed=+e.target.value;document.querySelector('#speed-output').textContent=speed.toFixed(2)+' m/s'}});app.addEventListener('keydown',e=>{if(e.target.matches('[data-task]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();taskDialog(+e.target.dataset.task)}});async function toggleFull(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('当前预览不允许全屏，可在独立窗口打开')}}window.addEventListener('resize',fit);document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&!dialog.open&&!e.target.matches('input'))toggleFull()});setInterval(()=>{if(!motion||document.hidden)return;tick++;const n=document.querySelector('#clock');if(n)n.textContent='10:'+String(24+Math.floor((tick+8)/60)).padStart(2,'0')+':'+String((tick+8)%60).padStart(2,'0')},1000);window.RobotDemo={setView:changeView,get view(){return mode},get selected(){return selected},get scene(){return scene},get acknowledged(){return alerts.filter(x=>x.ack).length}};render();


